('model-town', 'MULTIPOLYGON(((74.333019 31.49996,74.344112 31.473884,74.342229 31.473189,74.34114 31.474232,74.338335 31.475652,74.338081 31.475216,74.337018 31.47554,74.337132 31.475971,74.336229 31.476233,74.335725 31.476109,74.335843 31.475888,74.335217 31.475563,74.336385 31.474024,74.336784 31.474221,74.337046 31.474006,74.336553 31.473761,74.336683 31.47358,74.336971 31.473691,74.337123 31.473493,74.33683 31.473353,74.337057 31.472848,74.337186 31.471859,74.336575 31.471234,74.335956 31.470859,74.332243 31.469228,74.330803 31.469585,74.328677 31.47053,74.326934 31.470958,74.32679 31.470614,74.326057 31.470887,74.326147 31.471023,74.3255 31.471094,74.32554 31.471266,74.319239 31.470276,74.31815 31.470403,74.317377 31.470717,74.316591 31.470138,74.315233 31.469902,74.3093 31.472029,74.310078 31.473632,74.310046 31.474176,74.304886 31.48684,74.309488 31.49168,74.312234 31.490283,74.312844 31.491461,74.323831 31.49485,74.323837 31.495028,74.324686 31.495294,74.324663 31.495462,74.324842 31.495473,74.324815 31.495773,74.32535 31.495875,74.325393 31.497465,74.325164 31.498451,74.333019 31.49996)))')
), district_places AS (
    SELECT places.area_id, districts.slug,
        ST_Collect(COALESCE(places.boundary, places.location)) AS shapes,
        ST_Collect(places.location) AS points
    FROM places
    JOIN areas AS districts ON districts.id = places.area_id
    WHERE districts.parent_id = '00000000-0000-4000-8000-000000000101'
    GROUP BY places.area_id, districts.slug
), place_areas AS (
    SELECT area_id, slug, ST_ConvexHull(ST_Buffer(shapes::geography, GREATEST(400, 0.24 * ST_Distance(
        ST_SetSRID(ST_Point(ST_XMin(points), ST_YMin(points)), 4326)::geography,
        ST_SetSRID(ST_Point(ST_XMax(points), ST_YMax(points)), 4326)::geography)), 'quad_segs=2')::geometry) AS outline
    FROM district_places
), district_outlines AS (
    SELECT place_areas.area_id, CASE
        WHEN official_outlines.outline IS NULL THEN place_areas.outline
        ELSE ST_Union(ST_GeomFromText(official_outlines.outline, 4326), place_areas.outline)
    END AS outline
    FROM place_areas
    LEFT JOIN official_outlines ON official_outlines.slug = place_areas.slug
)
UPDATE areas SET boundary = ST_Multi(district_outlines.outline)
FROM district_outlines
WHERE areas.id = district_outlines.area_id;
